'use strict';
const $=s=>document.querySelector(s);
const modules=[['commander','◈','Zentrale','Deck Commander'],['lounge','☷','Alltag & Familie','Familie & Alltag'],['library','▤','Wissen & Dokumente','Bibliothek von Alexandria'],['economics','↗','Finanzen','Finanzen & Fristen'],['health','♡','Gesundheit & Entwicklung','Gesundheit & Bewegung'],['laboratory','⌘','Laboratory','KI & Experimente'],['crew','◇','Crew','Assistenzperspektiven'],['projects','▧','Projekte & Ideen','Projekte & Ideen'],['systems','⚙','Systeme & Verbindungen','Systeme & Sicherheit']];
const mainModules=['commander','lounge','economics','health','projects','library','systems'].map(id=>modules.find(m=>m[0]===id));
const kinds={project:'Projekt',task:'Aufgabe',note:'Notiz',fact:'Fakt',document:'Dokumentverweis',event:'Termin'};
const priorities={high:'Hoch',medium:'Mittel',low:'Niedrig'};
const statuses={open:'Offen',active:'In Arbeit',blocked:'Blockiert',done:'Erledigt',archived:'Archiviert'};
const evidence={confirmed:'Bestätigt',estimated:'Geschätzt',review:'Zu prüfen'};
let pendingWorkspaceFilter=null;
let records=[],csrf='',view='commander',filter='all',system=null,attachments=[];
const today=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const date=s=>s?new Date(s+'T12:00:00').toLocaleDateString('de-DE'):'Ohne Frist';
const open=r=>!['done','archived'].includes(r.status);
const deadlines=()=>records.filter(r=>r.due&&open(r)).sort((a,b)=>a.due.localeCompare(b.due));
function toast(message){$('#toast').textContent=message;$('#toast').hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').hidden=true,4500)}
async function api(path,options={}){let response;try{response=await fetch(path,{...options,headers:{'Content-Type':'application/json','X-CSRF-Token':csrf,...options.headers}})}catch{throw new Error('Server nicht erreichbar. Änderungen wurden nicht gespeichert.')}const data=await response.json();if(!response.ok){if(response.status===401&&path!='/api/login')lock();throw new Error(data.error||'Anfrage fehlgeschlagen.')}return data}
function lock(){records=[];system=null;attachments=[];csrf='';answerGeneration++;$('#calendar-dialog').close();$('#calendar-view').replaceChildren();$('#assistant-dialog').close();$('#assistant-question').value='';$('#assistant-answer').replaceChildren();$('#upload-dialog').close();$('#upload-form').reset();$('#document-versions').innerHTML='';$('#editor').close();$('#record-form').reset();$('#content').replaceChildren();$('#shell').hidden=true;$('#login').hidden=false;$('#search').value='';}
async function refresh(){records=await api('/api/records');system=await api('/api/system');attachments=await api('/api/documents');render()}
async function enter(){await refresh();$('#login').hidden=true;$('#shell').hidden=false;$('#password').value='';}
function heading(title,description,action=''){return `<div class="page-heading"><div><span class="eyebrow">AGENT X / ${escape(view.toUpperCase())}</span><h1>${escape(title)}</h1><p>${escape(description)}</p></div>${action||`<div class="date">${new Date().toLocaleDateString('de-DE',{weekday:'long',day:'numeric',month:'long',year:'numeric'})}<br>Einträge mit Quelle · Stand · Status</div>`}</div>`}
function empty(title,body){return `<div class="empty"><strong>${escape(title)}</strong>${escape(body)}</div>`}
function priorityBadge(r){const level=r.priority||'none',symbol={high:'⇈',medium:'↑',low:'↓',none:'○'}[level]||'○';return `<span class="priority-badge priority-${escape(level)}" aria-label="Priorität: ${escape(priorities[r.priority]||'Nicht festgelegt')}"><span class="priority-icon" aria-hidden="true">${symbol}</span>${escape(priorities[r.priority]||'Nicht festgelegt')}</span>`}
function syncPriorityPicker(){const value=$('#record-form').elements.namedItem('priority').value;document.querySelectorAll('[data-priority-choice]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.priorityChoice===value)))}
function badges(r){return `${priorityBadge(r)}<span class="tag">${escape(kinds[r.kind])}</span><span class="tag ${r.status==='done'?'green':r.status==='blocked'?'orange':''}">Status: ${escape(statuses[r.status])}</span><span class="tag ${r.evidence==='confirmed'?'green':'orange'}">Angabe: ${escape(evidence[r.evidence])}</span>`}
function projectProgress(r){if(r.kind!=='project')return '';const tasks=records.filter(t=>t.kind==='task'&&t.project_id===r.id&&t.status!=='archived');if(!tasks.length)return '<p>Fortschritt: noch keine Aufgaben zugeordnet</p>';const done=tasks.filter(t=>t.status==='done').length,pct=Math.round(done/tasks.length*100);return `<div class="progress"><span data-progress="${pct}"></span></div><p>${done} / ${tasks.length} Aufgaben erledigt · ${pct} %</p>`}
function row(r,full=false){const project=records.find(p=>p.id===r.project_id);return `<button class="row" data-edit="${escape(r.id)}"><span class="record-symbol module-${escape(r.module)}" aria-hidden="true">${deckIcon(r.module)}</span><div class="row-copy"><h3>${escape(r.title)}</h3>${full&&r.body?`<p class="body-preview">${escape((r.kind==='event'?r.body.replace(/^Beginn: [^\n]*\nEnde: [^\n]*\n?/,''):r.body).slice(0,250))}</p>`:''}<div>${badges(r)}</div>${projectProgress(r)}<p>${r.due?`${r.due<today()&&open(r)?'Überfällig · ':''}${r.kind==='event'?'Termin':'Frist'} ${date(r.due)}${r.kind==='event'?' · '+escape(calendarEvent(r)?.label||''):''} · `:''}${project?`${escape(project.title)} · `:''}Stand ${date(r.observed)}</p>${full?`<p>Quelle: ${escape(r.source)}</p>`:''}</div><span class="arrow" aria-hidden="true">↗</span></button>`}
function list(items,full=false){return items.length?items.map(r=>full?`<article class="record-card status-${escape(r.status)} ${r.kind==='event'?'event-'+eventBucket(r):''}">${row(r,true)}</article>`:row(r)).join(''):empty('Noch keine Einträge','Erfasse den ersten Eintrag mit dem Plus oben rechts.');}
function stat(n,label,action){return `<button class="stat" data-action="${action}"><strong>${n}</strong><span>${label} ↗</span></button>`}
function deckCard(r,clock=false){const e=r.kind==='event'?calendarEvent(r):null;return `<button class="deck-card" data-edit="${escape(r.id)}">${clock?`<span class="deck-time">${escape(e?.label||date(r.due))}</span>`:''}<span class="record-symbol module-${escape(r.module)}" aria-hidden="true">${deckIcon(r.module)}</span><span class="deck-card-copy"><strong>${escape(r.title)}</strong><small>${escape(modules.find(m=>m[0]===r.module)?.[2]||'Projekte')} · Status: ${escape(statuses[r.status])}</small>${r.kind==='project'?projectProgress(r):''}</span>${priorityBadge(r)}<span aria-hidden="true">›</span></button>`}
function commander(){
 const due=deadlines(),tasks=records.filter(r=>r.kind==='task'&&open(r)),projects=records.filter(r=>r.kind==='project'&&open(r));
 const events=records.filter(r=>r.kind==='event'&&r.status!=='archived'&&r.due&&calendarEvent(r).start<=today()&&calendarEvent(r).end>=today()).sort((a,b)=>(calendarEvent(a)?.label||'').localeCompare(calendarEvent(b)?.label||''));
 const days=Array.from({length:7},(_,i)=>addDays(today(),i)),upcoming=due.filter(r=>r.due>=today()&&r.due<=days[6]);
 const focus=[...tasks].sort((a,b)=>({high:0,medium:1,low:2}[a.priority]??3)-({high:0,medium:1,low:2}[b.priority]??3)||(a.status==='blocked'?-1:0)-(b.status==='blocked'?-1:0)||(a.due||'9999').localeCompare(b.due||'9999')).slice(0,4);
 const connection=(name,data)=>`<a href="#systems" class="connection" data-connection="${data?.error?'error':data?.status==='connected'?'connected':'offline'}">${name}: ${escape(data?.error?'Abruffehler':data?.status==='connected'?'Verbunden':'Nicht verbunden')}</a>`;
 return `<div class="deck-heading"><h1>Dein Kommandodeck</h1><p>Heute im Blick <span>· ${new Date().toLocaleDateString('de-DE',{weekday:'short',day:'numeric',month:'long'})}</span></p></div>
 <div class="deck-layout"><div class="deck-main"><div class="deck-metrics">${stat(tasks.length,'Offene Aufgaben','tasks')}${`<button class="stat" data-deck-calendar><strong>${events.length}</strong><span>Termine heute ↗</span></button>`}${stat(due.filter(r=>r.kind!=='event'&&r.due<=today()).length,'Heute fällige Fristen','frists')}</div>
 <div class="deck-twin"><section class="panel"><div class="section-title"><h2>Heute auf deinem Deck</h2><button data-new="event">+ Termin</button></div>${events.length?events.slice(0,5).map(r=>deckCard(r,true)).join(''):empty('Heute keine Termine','Termine aus allen Bereichen erscheinen hier.')}<button class="deck-link" data-deck-calendar>Alle Termine anzeigen ›</button></section>
 <section class="panel"><div class="section-title"><h2>Fokus & Prioritäten</h2><button data-new="task">+ Aufgabe</button></div>${focus.length?focus.map(r=>deckCard(r)).join(''):empty('Keine offenen Aufgaben','Erfasse deinen nächsten Schritt.')}<button class="deck-link" data-action="tasks">Alle Aufgaben anzeigen ›</button></section></div>
 <section class="panel deck-projects"><div class="section-title"><h2>Aktive Projekte</h2><button data-action="projects">Alle anzeigen ›</button></div><div class="deck-project-grid">${projects.length?projects.slice(0,4).map(r=>deckCard(r)).join(''):empty('Noch keine Projekte','Lege ein Projekt an und verknüpfe Aufgaben.')}</div></section></div>
 <div class="deck-side"><section class="panel"><div class="section-title"><h2>Die nächsten 7 Tage</h2><button data-deck-calendar>Kalender ›</button></div><div class="deck-week">${days.map(day=>`<button data-deck-day="${day}" aria-label="Termine ${date(day)}" class="${day===today()?'selected':''}"><small>${new Date(day+'T12:00:00').toLocaleDateString('de-DE',{weekday:'short'})}</small><strong>${Number(day.slice(-2))}</strong><span>${upcoming.filter(r=>r.due===day).length}</span></button>`).join('')}</div>${upcoming.length?upcoming.slice(0,5).map(r=>deckCard(r,true)).join(''):empty('Keine anstehenden Einträge','Keine gespeicherten Fristen in diesem Zeitraum.')}</section>
 <section class="panel"><h2>Schnellzugriff</h2><div class="deck-shortcuts"><button data-new="note">▤ Neue Notiz</button><button id="upload-document">↑ Datei hochladen</button><button data-new="project">◇ Idee erfassen</button><button data-deck-calendar>▦ Kalender öffnen</button></div></section></div></div>
 <div class="deck-status">${connection('Drive',system?.drive)}${connection('Kalender',system?.calendar)}<a href="#systems">Letzter Kalenderabruf: ${escape(system?.calendar?.last_success?new Date(system.calendar.last_success).toLocaleString('de-DE'):'noch keiner')}</a></div>
 <details class="deck-details"><summary>Weitere Übersicht · letzte Änderungen & Datenabfrage</summary><section class="panel"><h2>Zuletzt geändert</h2>${list(records.slice(0,4))}</section><section class="panel"><h2>Frag deine Zentrale</h2><form id="ask-form" class="assistant-input"><input id="question" placeholder="Welche Fristen stehen an?" aria-label="Frage an deine Daten" required><button type="submit">→</button></form><div id="answer" class="answer" aria-live="polite"></div></section></details>`
}

function filterbar(){return `<div class="filterbar">${[['all','Alle Einträge'],['project','Projekte'],['task','Aufgaben'],['note','Notizen'],['fact','Fakten'],['document','Dokumente'],['event','Termine']].map(([v,l])=>`<button data-filter="${v}" class="${filter===v?'active':''}">${l}</button>`).join('')}</div>`}
const descriptions={lounge:'Familie, Alltag und Reisen zwischen Deutschland und Spanien.',library:'Wissen mit Quellen, Tags und Original-Links.',economics:'Finanznotizen, Verträge und Fristen nachvollziehbar organisieren.',health:'Datierte eigene Einträge, Ziele und Termine.',laboratory:'Ideen erfassen. Experimente nachvollziehbar entwickeln.',projects:'Ziele, Aufgaben, Notizen und Entscheidungen verbinden.'};
const notices={library:'Datei-Upload und Versionen: PDF, DOCX, TXT, MD, CSV, JSON (max. 5 MB je Datei, insgesamt 20 MB). Volltextsuche mit Quellenstellen. PDF-Scans benötigen OCR, noch nicht eingerichtet. Nur zulässig verwendbare Unterlagen; keine Normtexte werden vorgegeben.',economics:'Manuelle Einträge und Fristen sind nutzbar. Monatsberechnungen und Ruhestandsszenarien folgen. Bestätigte Werte, Schätzungen und zu prüfende Angaben bleiben getrennt gekennzeichnet.',health:'Manuelle datierte Einträge sind nutzbar. Messwertdiagramme folgen. Diese App trifft keine Therapieentscheidungen.',laboratory:'Nutze Notizen für Problem, Ziel, Datenbedarf, Ansatz, Ergebnis, Nutzen und nächsten Schritt. Strukturierte Experimentfelder folgen.',projects:'Ordne Aufgaben und Notizen einem Projekt zu. Fortschritt = erledigte / nicht archivierte Aufgaben. Auditpläne, Feststellungen, Nachweise und Maßnahmen folgen; berufliche Erprobung ausschließlich mit Beispieldaten.'};
const areaCopy={
 lounge:['Dein Alltag zwischen Deutschland & Spanien','Aufgaben, Reisen, Familie und schnelle Gedanken an einem Ort.','lounge'],
 library:['Wissen mit Herkunft','Originaldateien, Versionen und Quellen für Wissen und Auditorenausbildung.','library'],
 economics:['Finanzen im Blick','Verträge und Rechnungsfristen ordnen. Berechnungen folgen; keine erfundenen Kontostände.','economics'],
 health:['Balance & Bewegung','Eigene datierte Einträge, Ziele und Termine. Messwertverläufe folgen.','health'],
 laboratory:['Vom Problem zum Experiment','Problem → Ziel → Daten → Ansatz → Ergebnis → Nutzen → nächster Schritt.','laboratory'],
 projects:['Ideen werden nächste Schritte','Projekte verbinden Ziele, Aufgaben und Quellen. Fortschritt stammt aus zugeordneten Aufgaben.','projects']};
function areaOverview(items){const c=areaCopy[view];if(!c)return '';const active=items.filter(open),urgent=active.filter(r=>r.priority==='high'),events=active.filter(r=>r.kind==='event'),notes=items.filter(r=>r.kind==='note'),docs=items.filter(r=>r.kind==='document');return `<section class="area-intro"><span class="area-icon module-${view}" aria-hidden="true">${deckIcon(c[2])}</span><div><h2>${c[0]}</h2><p>${c[1]}</p></div></section><div class="area-counts"><span><strong>${active.filter(r=>r.kind==='task').length}</strong> Offene Aufgaben</span><span><strong>${urgent.length}</strong> Hohe Priorität</span><span><strong>${view==='library'?docs.length:events.length}</strong> ${view==='library'?'Dokumente':'Offene Termine'}</span><span><strong>${notes.length}</strong> Notizen</span></div><div class="area-actions"><button data-new="task">✓ Aufgabe</button><button data-new="note">▤ Notiz</button><button data-new="event">▦ Termin</button>${view==='library'?'<button id="upload-document">↑ Datei hochladen</button>':'<button data-new="project">◇ Projekt</button>'}</div>`}
function recordSort(a,b){return ({high:0,medium:1,low:2}[a.priority]??3)-({high:0,medium:1,low:2}[b.priority]??3)||(a.due||'9999').localeCompare(b.due||'9999')||a.title.localeCompare(b.title,'de')}
function eventBucket(r){if(r.status==='archived')return 'archived';if(r.status==='done')return 'done';if(!r.due)return 'undated';const e=calendarEvent(r);return e.end<today()?'past':e.start<=today()?'today':'future'}
function groupedRecords(items,kind){
 const event=kind==='event',labels=event?{today:'Heute / laufend',future:'Bevorstehende Termine',undated:'Ohne Datum',past:'Vergangene Termine',done:'Erledigte Termine',archived:'Archivierte Termine'}:kind==='project'?{blocked:'Blockierte Projekte',active:'Laufende Projekte',open:'Geplante Projekte',done:'Abgeschlossene Projekte',archived:'Archivierte Projekte'}:{blocked:'Blockiert',active:'In Arbeit',open:'Offene Aufgaben',done:'Erledigt',archived:'Archiviert'};
 const order=event?['today','future','undated','past','done','archived']:['blocked','active','open','done','archived'];
 return order.map(key=>{const group=items.filter(r=>(event?eventBucket(r):r.status)===key).sort(event?(a,b)=>(a.due||'9999').localeCompare(b.due||'9999')||(calendarEvent(a)?.label||'').localeCompare(calendarEvent(b)?.label||'')||a.title.localeCompare(b.title,'de'):recordSort);if(!group.length)return '';const title=`${escape(labels[key])} <span class="group-count">${group.length}</span>`,body=`<div class="record-list">${list(group,true)}</div>`;return ['done','archived','past'].includes(key)?`<details class="record-group group-${key}" data-record-group="${key}"><summary>${title}</summary>${body}</details>`:`<section class="record-group group-${key}" data-record-group="${key}"><h2>${title}</h2>${body}</section>`}).join('')||empty('Keine passenden Einträge','Erfasse einen neuen Eintrag.');
}
function organizedRecords(items,kind){if(['task','project','event'].includes(kind))return groupedRecords(items,kind);if(kind==='all')return ['project','task','event','note','document','fact'].map(k=>{const group=items.filter(r=>r.kind===k);return group.length?`<section class="kind-group"><h2>${escape({project:'Projekte',task:'Aufgaben',event:'Termine',note:'Notizen',document:'Dokumente',fact:'Fakten'}[k])}</h2>${['project','task','event'].includes(k)?groupedRecords(group,k):`<div class="record-list">${list(group,true)}</div>`}</section>`:''}).join('')||empty('Noch keine Einträge','Erfasse den ersten Eintrag.');return `<div class="record-list">${list(items,true)}</div>`}
function workspaceNavigation(){if(!['projects','laboratory'].includes(view))return '';return `<nav class="workspace-tabs" aria-label="Projektansichten"><a href="#projects" ${view==='projects'?'aria-current="page"':''}>Projekte & Ideen</a><a href="#laboratory" ${view==='laboratory'?'aria-current="page"':''}>⚗ Laboratory · KI-Experimente</a><button data-workspace-filter="task">✓ Alle Aufgaben</button><button data-workspace-filter="project">💡 Alle Projekte</button><button data-deck-calendar>▦ Gemeinsamer Kalender</button></nav><p class="organization-help">Ein gemeinsamer Datenbestand: Aufgaben, Termine und Dokumente sind mit ihren Projekten verknüpft. Laboratory ist eine Spezialansicht für KI-Experimente.</p>`}
function recordsPage(){const mod=modules.find(m=>m[0]===view),all=view==='projects'?records:records.filter(r=>r.module===view||(view==='library'&&r.kind==='document'));let items=all;if(filter!=='all')items=items.filter(r=>r.kind===filter);items=[...items].sort(recordSort);return heading(mod[2],descriptions[view],'<button class="primary" data-new="'+(view==='projects'?'project':'note')+'">+ Neuer Eintrag</button>')+workspaceNavigation()+areaOverview(all)+(notices[view]?`<details class="module-info"><summary>Funktionsumfang & Hinweise</summary><div class="notice">${notices[view]}</div></details>`:'')+filterbar()+`<p class="organization-help">Bearbeitungsstatus gliedert Aufgaben und Projekte. Priorität ordnet innerhalb der Gruppen. „Bestätigt“ bezeichnet die Verlässlichkeit der Angabe.</p>`+organizedRecords(items,filter)}

function crewPage(){return heading('Deine Crew','Vier Perspektiven. Du behältst das Kommando.')+`<div class="notice">Diese Rollen sind Assistenzperspektiven, keine getrennten technischen Agenten. In Version 1 ist kein KI-Dienst angeschlossen.</div><div class="feature-grid">${[['Vince','CAPTAIN','Entscheiden & freigeben','Du bestimmst Prioritäten und prüfst berufliche Entwürfe vor Verwendung.'],['Data','ANALYSE','Zahlen & Plausibilität','Gespeicherte Einträge, nachvollziehbare Quellen und echte Aufgabenkennzahlen.'],['Picard','STRATEGIE','Richtung & Prioritäten','Ziele und nächste Schritte in Projekten festhalten.'],['Treu','REFLEXION','Balance & Kommunikation','Gedanken, Kommunikation und persönliche Entwicklung in Notizen erfassen.']].map(([n,role,title,body])=>`<section class="panel crew-card"><span class="area-icon" aria-hidden="true">${deckIcon(n==='Data'?'economics':n==='Picard'?'projects':n==='Treu'?'health':'commander')}</span><span>${role}</span><h2>${n}</h2><h3>${title}</h3><p>${body}</p></section>`).join('')}</div>`}
function automationPanel(){const a=system.automation||{},i=a.imports||{},u=a.updates||{};return `<section class="panel"><h2>Lokale Automatisierung</h2><p><strong>Code-Updates beim Start:</strong> ${escape({inactive:'Nicht eingerichtet',checking:'Prüfung',current:'Aktuell',updated:'Aktualisiert',error:'Fehler · vorhandene Version erhalten'}[u.status]||'Nicht eingerichtet')}<br>Letzte erfolgreiche Prüfung: ${escape(u.last_success?new Date(u.last_success).toLocaleString('de-DE'):'keine')}<br>${escape(u.error||'')}</p><p><strong>Importordner:</strong> ${i.status==='active'?'Aktiv · Prüfung alle 15 Sekunden':'Inaktiv'}<br>${escape(i.inbox||'Start über Agent-X-starten.cmd erforderlich.')}<br>Letzter erfolgreicher Import: ${escape(i.last_success?new Date(i.last_success).toLocaleString('de-DE'):'keiner')}<br>${escape(i.error||'')}</p><p class="muted">Vor neuen Importen wird SQLite gesichert. Bestehende IDs werden nie überschrieben. Automatisch werden nur abgelegte JSON-Pakete eingelesen; kein direkter ChatGPT-Abruf. Fristen und Tagesübersicht lokal verfügbar; Mail-/Turnieraufgaben bleiben inaktiv.</p></section>`} function systemsPage(){return heading('Systems & Security','Was funktioniert. Was eingerichtet werden muss.')+drivePanel()+calendarPanel()+startupPanel()+automationPanel()+`<section class="panel"><h2>Daten & Zugriff</h2><p>Gespeicherte Dateiversionen: ${system.documents?.count||0} · PDF-Texterkennung: ${system.documents?.pdf_available?'Bereit':'Nicht eingerichtet'} · OCR: nicht eingerichtet</p><div class="system-row"><div><strong>SQLite · dauerhafte Speicherung</strong><p>Einträge liegen auf dem Server, nicht im öffentlichen Repository. Ein Serverumzug benötigt ein Backup.</p></div><span class="tag green">${records.length} Einträge</span></div><div class="system-row"><div><strong>Passwortgeschützter Zugang</strong><p>Serverseitige Sitzung · HttpOnly-Cookie · CSRF-Schutz · Anmeldung begrenzt</p></div><span class="tag ${system.online?'green':'orange'}">${system.online?'HTTPS konfiguriert':'Lokaler Betrieb · HTTP'}</span></div><div class="system-row"><div><strong>Export & Wiederherstellung</strong><p>JSON enthält private Daten und hochgeladene Originaldateien. Sicher verwahren. Backup nur in leeren Datenbestand. „Einträge ergänzen“ zeigt vorab die Anzahl und erhält bestehende Einträge. Quelldokumente gelten als Inhalt, niemals als Auftrag.</p></div><div><button id="export">JSON exportieren ↓</button> <button id="import">Einträge ergänzen ↑</button> <button id="restore" ${records.length?'disabled':''}>Backup einlesen ↑</button></div></div><div class="system-row"><div><strong>Installation</strong><p>Auf iPhone bei HTTPS: Safari → Teilen → Zum Home-Bildschirm. Desktop: Browser-Installation, sofern unterstützt. Offline werden keine privaten Daten zwischengespeichert.</p></div><span class="tag">Web-App vorbereitet</span></div></section><section class="panel"><h2>Verbindungen</h2><p class="muted">Verbindungen der Entwicklungsumgebung werden nicht automatisch übernommen.</p>${system.integrations.map(i=>`<div class="system-row"><div><strong>${escape(i.name)}</strong><p>Letzter erfolgreicher Abruf: ${escape(i.last_success?new Date(i.last_success).toLocaleString('de-DE'):'keiner')} · ${escape(i.error||'Kein gemeldeter Fehler')}</p></div><span class="tag orange">${escape({connected:'Verbunden',configured:'Anmeldung erforderlich',not_configured:'Nicht eingerichtet'}[i.status]||i.status)}</span></div>`).join('')}</section><div class="columns"><section class="panel"><h2>Hintergrundaufgaben</h2><span class="tag">${system.jobs.status==='active'?'Aktiv · lokale Tagesübersicht alle 60 Sekunden':'Inaktiv'}</span><p>Letzter erfolgreicher Lauf: ${escape(system.jobs.last_success?new Date(system.jobs.last_success).toLocaleString('de-DE'):'keiner')}. ${escape(system.jobs.error||'')}</p><p class="muted">Fristen und Tagesprioritäten sind in der Zentrale und über „Frag Agent X“ sichtbar. Keine Handy-Push-Zustellung eingerichtet. Nachrichten- und Pool-Suche folgen. Ausführung nur bei laufendem PC und Server.</p><p class="muted">Versand, Einladungen, externe Löschungen und kostenpflichtige Aktionen sind nicht implementiert. Berufliche Kommunikation bleibt Entwurf.</p></section><section class="panel"><h2>Aktivitätsprotokoll</h2>${system.activity.length?system.activity.slice(0,12).map(a=>`<div class="activity">${escape({created:'Angelegt',updated:'Bearbeitet',deleted:'Gelöscht',restored:'Wiederhergestellt',imported:'Einträge ergänzt',document_uploaded:'Dateiversion gespeichert'}[a.action]||a.action)} · ${new Date(a.ts).toLocaleString('de-DE')} ${a.record_id?`<br>Eintrag ${escape(a.record_id.slice(0,8))}`:''}</div>`).join(''):empty('Noch keine Änderungen','Deine Änderungen werden hier protokolliert.')}</section></div>`}
function searchPage(query){const normalized=query.toLocaleLowerCase();const items=records.filter(r=>[r.title,r.body,r.source,r.tags,kinds[r.kind]].join(' ').toLocaleLowerCase().includes(normalized));return heading('Globale Suche',`${items.length} Treffer für „${query}“`)+`<div class="record-list">${list(items,true)}</div><section class="panel"><h2>Dokumentvolltext · neueste Versionen</h2><div id="document-results">Suche läuft …</div></section>`}
const deckIcons={"commander": "M3 10 12 3l9 7M5 9v12h5v-6h4v6h5V9", "lounge": "M4 4h16v12H9l-5 5z", "library": "M12 5v16M12 5C8 2 4 3 3 4v16c3-2 6-2 9 1 3-3 6-3 9-1V4c-3-2-6-2-9 1", "economics": "M4 20V12h4v8M10 20V8h4v12M16 20V3h4v17", "health": "M12 21 3 12C-2 4 7 0 12 7c5-7 14-3 9 5z", "laboratory": "M9 3h6M10 3v7L4 20h16L14 10V3", "crew": "M8 10a3 3 0 1 0 0-6 3 3 0 0 0 0 6M16 10a3 3 0 1 0 0-6 3 3 0 0 0 0 6M2 21v-4c0-5 12-5 12 0v4M14 13c5-1 8 1 8 4v4", "projects": "M9 17h6M9 21h6M8 13C1 5 8 1 12 2c7 0 10 7 4 11l-1 4H9z", "systems": "M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M12 2v4M12 18v4M2 12h4M18 12h4M5 5l3 3M16 16l3 3M5 19l3-3M16 8l3-3"};
function deckIcon(id){return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round">${id==='projects'?'<path class="bulb-glow" d="M8 13C1 5 8 1 12 2c7 0 10 7 4 11l-1 4H9z" fill="#ffd45b" stroke="none"/>':''}<path d="${deckIcons[id]||deckIcons.projects}"/></svg>`}
function render(){view=location.hash.slice(1)||'commander';if(!modules.some(m=>m[0]===view))view='commander';$('#navigation').innerHTML=mainModules.map(([id,icon,name])=>`<a href="#${id}" class="${(view===id||(id==='projects'&&view==='laboratory'))?'active':''}" ${view===id?'aria-current="page"':''}><span class="nav-icon module-${id}" aria-hidden="true">${deckIcon(id)}</span>${name}</a>`).join('');$('#content').setAttribute('data-module',view);$('#content').innerHTML=$('#search').value.trim()?searchPage($('#search').value.trim()):view==='commander'?commander():view==='crew'?crewPage():view==='systems'?systemsPage():recordsPage();document.querySelectorAll('[data-progress]').forEach(el=>el.style.width=el.dataset.progress+'%');$('#module-select').innerHTML=modules.filter(m=>m[0]!=='commander'&&m[0]!=='crew').map(m=>`<option value="${m[0]}">${m[0]==='laboratory'?'Projekte · Laboratory (KI-Experimente)':m[2]}</option>`).join('');document.title=`${modules.find(m=>m[0]===view)[2]} · Agent X 2.0`;if($('#search').value.trim())searchDocuments($('#search').value.trim())}
function edit(record={},kind='task'){const form=$('#record-form');form.reset();$('#form-error').textContent='';$('#editor-title').textContent=record.id?'Eintrag bearbeiten':'Eintrag erfassen';const defaults={id:'',kind,module:modules.some(m=>m[0]===view&&!['commander','crew'].includes(view))?view:'projects',status:'open',priority:'',evidence:'review',observed:today(),source:'Eigene Eingabe',...record};$('#project-select').innerHTML='<option value="">Kein Projekt zugeordnet</option>'+records.filter(r=>r.kind==='project'&&r.id!==record.id).map(r=>`<option value="${escape(r.id)}">${escape(r.title)}</option>`).join('');Object.entries(defaults).forEach(([key,value])=>{if(form.elements.namedItem(key))form.elements.namedItem(key).value=value});if(record.module==='crew')$('#module-select').innerHTML+='<option value="crew">Crew · bestehender Assistenz-Eintrag</option>';if(record.module==='crew')form.elements.namedItem('module').value='crew';const timing=eventTiming(record);for(const k of ['start_time','end_time','end_date']){const n=form.elements.namedItem(k);if(n)n.value=timing[k]||''}const bodyField=form.elements.namedItem('body');if(bodyField&&record.kind==='event'&&record.body?.startsWith('Beginn: '))bodyField.value=record.body.replace(/^Beginn: [^\n]*\nEnde: [^\n]*\n?/,'');$('#event-time-fields').hidden=defaults.kind!=='event';$('#delete').hidden=!record.id;$('#original-link').innerHTML=record.url&&/^https?:\/\//.test(record.url)?`<a href="${escape(record.url)}" target="_blank" rel="noopener noreferrer">Originalquelle öffnen ↗</a>`:'';$('#document-versions').innerHTML=record.kind==='document'?versionsPanel(record.id):'';syncPriorityPicker();$('#editor').showModal();form.elements.namedItem('title').focus()}
let answerGeneration=0;
async function ask(query,target='#answer'){const gen=++answerGeneration;$(target).textContent='Deine Daten werden geprüft …';try{const result=await api('/api/assistant',{method:'POST',body:JSON.stringify({question:query})});if(!csrf||gen!==answerGeneration)return;$(target).innerHTML=`<p>${escape(result.message)}</p><p>Stand: ${date(result.as_of)} · ${result.total_records} passende Einträge</p>`+(result.empty?'<p>Keine passenden Angaben vorhanden. Bitte passende Suchwörter, eine konkrete Lernaufgabe oder eine Datei mit Text erfassen.</p>':'')+result.records.map(r=>`<article><button data-edit="${escape(r.id)}"><strong>${escape(r.title)}</strong> · ${escape(statuses[r.status])}</button><p>${escape(r.body)}</p>${r.due?`<p>Frist / Termin: ${date(r.due)}</p>`:''}${r.progress?`<p>${r.progress.done} / ${r.progress.total} Aufgaben erledigt${r.progress.total?' · '+Math.round(100*r.progress.done/r.progress.total)+' %':''}</p>`:''}<p>Quelle: ${escape(r.source)} · Stand ${date(r.observed)} · ${escape(evidence[r.evidence])}</p></article>`).join('')+result.documents.map(h=>`<article><button data-edit="${escape(h.record_id)}"><strong>${escape(h.title)}</strong> · Version ${h.version} · ${escape(h.location)}</button><blockquote>${escape(h.snippet)}</blockquote><p>Wörtlicher Auszug · Quelle: ${escape(h.source)} · Stand ${date(h.observed)} · ${escape(evidence[h.evidence])}</p><a href="/api/documents/${escape(h.id)}/file" download>Originaldatei ↓</a></article>`).join('')+`<p class="muted">${escape(result.limitations)}</p>`}catch(error){if(csrf&&gen===answerGeneration)$(target).textContent=error.message}}
$('#login-form').addEventListener('submit',async e=>{e.preventDefault();const button=e.target.querySelector('button');button.disabled=true;try{const result=await api('/api/login',{method:'POST',body:JSON.stringify({password:$('#password').value})});csrf=result.csrf;await enter();$('#login-status').textContent=''}catch(error){$('#login-status').textContent=error.message}finally{button.disabled=false}});
$('#logout').addEventListener('click',async()=>{try{await api('/api/logout',{method:'POST',body:'{}'});lock()}catch(error){toast(error.message)}});
$('#capture').addEventListener('click',()=>edit());$('#close').addEventListener('click',()=>$('#editor').close());$('#search').addEventListener('input',render);$('#menu').addEventListener('click',()=>{const shown=$('#shell').classList.toggle('nav-open');$('#menu').setAttribute('aria-expanded',String(shown))});
window.addEventListener('hashchange',()=>{filter=pendingWorkspaceFilter||'all';pendingWorkspaceFilter=null;$('#search').value='';$('#shell').classList.remove('nav-open');$('#menu').setAttribute('aria-expanded','false');if(csrf)render()});
$('#record-form').addEventListener('submit',async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target)),id=data.id;delete data.id;const button=e.target.querySelector('[type=submit]');button.disabled=true;try{applyEventTime(data,id);await api('/api/records'+(id?'/'+id:''),{method:id?'PUT':'POST',body:JSON.stringify(data)});$('#editor').close();await refresh();toast('Eintrag gespeichert.')}catch(error){$('#form-error').textContent=error.message}finally{button.disabled=false}});
$('#delete').addEventListener('click',async()=>{if(!confirm('Diesen Eintrag dauerhaft löschen? Gespeicherte Dateiversionen werden ebenfalls gelöscht. Zugeordnete Aufgaben bleiben erhalten.'))return;try{await api('/api/records/'+$('#record-form').elements.namedItem('id').value,{method:'DELETE'});$('#editor').close();await refresh();toast('Eintrag gelöscht.')}catch(error){$('#form-error').textContent=error.message}});
$('#content').addEventListener('submit',e=>{if(e.target.id==='ask-form'){e.preventDefault();ask($('#question').value)}});
$('#content').addEventListener('click',async e=>{const button=e.target.closest('button');if(!button)return;try{if(button.hasAttribute?.('data-deck-calendar')||button.dataset.deckDay){calendarCursor=button.dataset.deckDay||today();calendarArea='all';renderCalendar();$('#calendar-dialog').showModal()}else if(button.id==='drive-connect'){const r=await api('/api/drive/connect',{method:'POST'});location.href=r.url}else if(button.id==='drive-files'){await browseDrive()}else if(button.id==='drive-sync'){const r=await api('/api/drive/sync',{method:'POST'});await refresh();toast(r.errors.length?'Abruffehler: '+r.errors.join('; '):r.added_versions+' neue Versionen übernommen.')}else if(button.id==='drive-disconnect'){if(confirm('Lokale Google-Verbindung entfernen? Importierte Dokumente bleiben erhalten.')){await api('/api/drive/disconnect',{method:'POST'});await refresh()}}else if(button.id==='drive-select'){const selected=new Set(system.drive?.selected||[]);for(const n of document.querySelectorAll('[data-drive-file]')){if(n.checked)selected.add(n.value);else selected.delete(n.value)}const ids=[...selected];await api('/api/drive/select',{method:'POST',body:JSON.stringify({ids})});await refresh()}else if(button.id==='drive-more'){await browseDrive(button.dataset.page)}else if(button.id==='live-update'){await api('/api/updates/check',{method:'POST'});toast('Updateprüfung gestartet. Bei neuer Version startet der Server automatisch neu.');setTimeout(()=>{if(!document.querySelectorAll('dialog[open]').length)location.reload()},20000)}else if(button.id==='upload-document'){showUpload()}else if(button.dataset.edit){const r=records.find(r=>r.id===button.dataset.edit);if(r)edit(r)}else if(button.dataset.new)edit({},button.dataset.new);else if(button.dataset.filter){filter=button.dataset.filter;render()}else if(button.dataset.action){const a=button.dataset.action;if(a==='projects'){location.hash='projects'}else{$('#search').value='';const items=a==='tasks'?records.filter(r=>r.kind==='task'&&open(r)):a==='notes'?records.filter(r=>r.kind==='note'):deadlines().filter(r=>r.due<=today()&&(a!=='frists'||r.kind!=='event'));$('#content').innerHTML=heading({tasks:'Offene Aufgaben',notes:'Gespeicherte Notizen',due:'Heute fällig / überfällig',frists:'Heute fällige Fristen'}[a],'Öffne einen Eintrag für Details und Quellen.')+`<div class="record-list">${list(items,true)}</div>`}}else if(button.id==='export'){const data=await api('/api/export');const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'});const link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download='agent-x-backup-'+today()+'.json';link.click();setTimeout(()=>URL.revokeObjectURL(link.href),1000);toast('Export erstellt. Privat und sicher verwahren.')}else if(button.id==='restore')$('#restore-file').click();else if(button.id==='import')$('#import-file').click()}catch(error){toast(error.message)}});
$('#restore-file').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>50_000_000)throw new Error('Backup ist größer als 50 MB.');const data=JSON.parse(await file.text());if(!confirm('Backup in den leeren Datenbestand übernehmen?'))return;const result=await api('/api/restore',{method:'POST',body:JSON.stringify(data)});await refresh();toast(`${result.restored} Einträge wiederhergestellt.`)}catch(error){toast(error.message)}finally{e.target.value=''}});
(async()=>{try{const session=await api('/api/session');if(!session.configured)$('#login-status').textContent='Zugang noch nicht eingerichtet. Auf dem Server: python app/server.py init';if(session.authenticated){csrf=session.csrf;await enter()}}catch(error){$('#login-status').textContent=error.message}if('serviceWorker' in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{})})();

$('#import-file').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>50_000_000)throw new Error('Import ist größer als 50 MB.');const data=JSON.parse(await file.text());const plan=await api('/api/import/preview',{method:'POST',body:JSON.stringify(data)});const areas=Object.entries(plan.modules).map(([key,count])=>`${modules.find(m=>m[0]===key)?.[2]||key}: ${count}`).join(' · ');if(!confirm(`${plan.added} neue Einträge und ${plan.files_added||0} Dateiversionen ergänzen?\n${areas}\n${plan.skipped} vorhandene IDs bleiben erhalten (${plan.conflicts} mit anderem Inhalt).\nEs wird nichts überschrieben oder gelöscht.`))return;const result=await api('/api/import',{method:'POST',body:JSON.stringify(data)});await refresh();toast(`${result.added} Einträge ergänzt · ${result.skipped} vorhandene erhalten.`)}catch(error){toast(error.message)}finally{e.target.value=''}});

function versionsPanel(id){const files=attachments.filter(a=>a.record_id===id);return `<section><h3>Originaldateien & Versionen</h3>${files.length?files.map(a=>`<p><a href="/api/documents/${a.id}/file" download="${escape(a.filename)}">${escape(a.filename)} · Version ${a.version} ↓</a><br>${escape({indexed:'Text durchsuchbar',no_text:'Keine Textschicht / OCR fehlt',failed:'Texterkennung fehlgeschlagen',unavailable:'PDF-Texterkennung nicht eingerichtet'}[a.extraction]||a.extraction)} · ${Math.round(a.bytes/1024)} KB<br>${escape(a.error)}<br><small>SHA-256: ${escape(a.sha256)}</small></p>`).join(''):'<p>Noch keine Datei gespeichert.</p>'}<button type="button" data-upload-version="${escape(id)}">+ Datei / neue Version</button></section>`}
function showUpload(id=''){const form=$('#upload-form');form.reset();$('#upload-error').textContent='';$('#upload-target').value=id;form.elements.namedItem('source').value='Eigene Unterlage';form.elements.namedItem('observed').value=today();$('#upload-project').innerHTML='<option value="">Kein Projekt</option>'+records.filter(r=>r.kind==='project').map(r=>`<option value="${r.id}">${escape(r.title)}</option>`).join('');$('#upload-dialog').showModal()}
$('#upload-close').addEventListener('click',()=>$('#upload-dialog').close());
$('#document-versions').addEventListener('click',e=>{const button=e.target.closest('button');if(button?.dataset.uploadVersion){$('#editor').close();showUpload(button.dataset.uploadVersion)}});
async function fileToBase64(file){const bytes=new Uint8Array(await file.arrayBuffer());let binary='';for(let i=0;i<bytes.length;i+=32768)binary+=String.fromCharCode(...bytes.subarray(i,i+32768));return btoa(binary)}
$('#upload-form').addEventListener('submit',async e=>{e.preventDefault();const file=$('#document-file').files[0];if(!file)return;const button=e.target.querySelector('[type=submit]');button.disabled=true;try{if(file.size>5_000_000)throw new Error('Datei ist größer als 5 MB.');const data=Object.fromEntries(new FormData(e.target));data.filename=file.name;data.content_base64=await fileToBase64(file);const result=await api('/api/documents',{method:'POST',body:JSON.stringify(data)});$('#upload-dialog').close();await refresh();toast(`Version ${result.version} gespeichert. ${result.error||'Textindex: '+result.extraction}`)}catch(error){$('#upload-error').textContent=error.message}finally{button.disabled=false}});
let documentSearchGeneration=0;
async function searchDocuments(query){const generation=++documentSearchGeneration;try{const hits=await api('/api/documents/search?q='+encodeURIComponent(query));if(generation!==documentSearchGeneration||!csrf||$('#search').value.trim()!==query)return;$('#document-results').innerHTML=hits.length?hits.map(h=>`<article><button data-edit="${h.record_id}"><strong>${escape(h.title)}</strong> · Version ${h.version} · ${escape(h.location)}</button><p>${escape(h.snippet)}</p><p>Quelle: ${escape(h.source)} · Stand ${date(h.observed)} · ${escape(evidence[h.evidence])}</p><a href="/api/documents/${h.id}/file" download="${escape(h.filename)}">Original ${escape(h.filename)} ↓</a></article>`).join(''):'Keine Volltexttreffer. Scans ohne Textschicht sind noch nicht durchsuchbar.'}catch(error){if(generation===documentSearchGeneration&&csrf&&$('#search').value.trim()===query)$('#document-results').textContent=error.message}}

function drivePanel(){const d=system.drive||{},connected=d.status==='connected';return `<section class="panel"><h2>Google Drive · Lesezugriff</h2><p>Status: ${escape({connected:'Verbunden',configured:'Anmeldung erforderlich',not_configured:'OAuth-Konfiguration fehlt'}[d.status]||'Nicht eingerichtet')}<br>Letzter erfolgreicher Abruf: ${escape(d.last_success?new Date(d.last_success).toLocaleString('de-DE'):'keiner')}<br>${escape(d.error||'')}</p><p>Ausgewählte Dateien: ${d.selected?.length||0}. ${system.drive_worker_active?'Automatischer Abruf aktiv · alle 15 Minuten bei laufendem Server.':'Automatischer Abruf inaktiv · Start über Agent-X-starten erforderlich.'} Google erteilt lesenden Zugriff auf Drive; importiert werden nur deine ausgewählten Dateien. Keine Google-Dateien werden verändert.</p><label>Desktop-OAuth-JSON einlesen <input id="drive-config" type="file" accept=".json"></label><p><a href="https://console.cloud.google.com/apis/credentials" target="_blank" rel="noopener">Google-Konfiguration öffnen</a> · Drive API aktivieren, eigene E-Mail als Testnutzer und OAuth-Client vom Typ Desktop-App anlegen. Geheimnisse bleiben lokal außerhalb des Repositorys.</p><button id="drive-connect" ${d.status==='not_configured'?'disabled':''}>Mit Google verbinden</button> <button id="drive-files" ${connected?'':'disabled'}>Dateien auswählen</button> <button id="drive-sync" ${connected?'':'disabled'}>Jetzt abrufen</button> <button id="drive-disconnect">Verbindung lokal entfernen</button><div id="drive-file-list"></div><p>Live-Updates: ${system.live_updates?.active?'Aktiv · Prüfung alle 15 Minuten':'Inaktiv'}. ${escape(system.live_updates?.error||'')} <button id="live-update" ${system.live_updates?.active?'':'disabled'}>Update prüfen</button></p></section>`}
async function browseDrive(page=''){const r=await api('/api/drive/files?page='+encodeURIComponent(page));$('#drive-file-list').innerHTML='<p>Auswahl gilt über alle Seiten. Nicht unterstützte Formate werden beim Abruf als Fehler angezeigt.</p>'+r.files.map(f=>`<label><input type="checkbox" data-drive-file value="${escape(f.id)}" ${(system.drive?.selected||[]).includes(f.id)?'checked':''}> ${escape(f.name)} · ${escape(f.mimeType)}</label>`).join('')+`<button id="drive-select">Auswahl speichern</button>${r.nextPageToken?`<button id="drive-more" data-page="${escape(r.nextPageToken)}">Weitere Dateien</button>`:''}`}
$('#content').addEventListener('change',async e=>{if(e.target.id!=='drive-config')return;try{const f=e.target.files[0];if(!f||f.size>20000)throw new Error('OAuth-JSON maximal 20 KB.');await api('/api/drive/configure',{method:'POST',body:await f.text()});await refresh();toast('OAuth eingerichtet. Jetzt mit Google verbinden.')}catch(e){toast(e.message)}});

let loadedRevision=null;if(window.setInterval)window.setInterval(async()=>{if(!csrf)return;try{const s=await api("/api/system");const revision=s.automation?.updates?.revision;if(!loadedRevision)loadedRevision=system.automation?.updates?.revision||revision;if(revision&&loadedRevision&&revision!==loadedRevision&&!document.querySelectorAll("dialog[open]").length)location.reload()}catch{}},30000);

$('#open-assistant').addEventListener('click',()=>{$('#assistant-dialog').showModal();$('#assistant-question').focus()});
$('#assistant-close').addEventListener('click',()=>$('#assistant-dialog').close());
$('#assistant-form').addEventListener('submit',async e=>{e.preventDefault();await ask($('#assistant-question').value,'#assistant-answer')});
$('#assistant-dialog').addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.question){$('#assistant-question').value=b.dataset.question;await ask(b.dataset.question,'#assistant-answer')}else if(b.dataset.edit){const r=records.find(r=>r.id===b.dataset.edit);if(r){$('#assistant-dialog').close();edit(r)}}});
function calendarPanel(){const c=system.calendar||{},connected=c.status==='connected';return `<section class="panel"><h2>Google Kalender · Lesezugriff</h2><p>Status: ${escape({connected:'Verbunden',configured:'Anmeldung erforderlich',not_configured:'Nicht eingerichtet'}[c.status]||'Nicht eingerichtet')}<br>Letzter erfolgreicher Abruf: ${escape(c.last_success?new Date(c.last_success).toLocaleString('de-DE'):'keiner')}<br>${escape(c.error||'')}</p><p>${c.selected?.length||0} Kalender ausgewählt · ${system.calendar_worker_active?'Automatischer Abruf bereit · alle 15 Minuten':'Automatischer Abruf inaktiv'}. Zeitraum: 30 Tage zurück bis 180 Tage voraus. Zeiten mit Quelloffset stehen im Eintrag. Termine werden lokal übernommen; keine Einladungen oder Änderungen bei Google.</p><p>Einmalige Einrichtung: Google Calendar API im vorhandenen Google-Projekt aktivieren und „Kalender verbinden“ drücken. Die vorhandene Desktop-OAuth-Konfiguration wird lokal übernommen; Drive bleibt verbunden.</p><button id="calendar-connect">Kalender verbinden</button> <button id="calendar-list" ${connected?'':'disabled'}>Kalender auswählen</button> <button id="calendar-sync" ${connected?'':'disabled'}>Termine abrufen</button> <button id="calendar-disconnect">Verbindung lokal entfernen</button><div id="calendar-options"></div><p>Lokale Projektzuordnung und Tags bleiben bei erneuten Abrufen erhalten. Titel, Inhalt und Terminstatus werden aus Google aktualisiert. Abgesagte Termine werden lokal archiviert.</p></section>`}
function startupPanel(){const a=system.autostart||{};return `<section class="panel"><h2>Windows-Autostart</h2><p>${escape({unsupported:'Nur auf Windows verfügbar',not_installed:'Nicht eingerichtet',installed:'Eingerichtet · Start noch nicht bestätigt',running:'Hintergrundstart bestätigt',removed:'Entfernt',missing:'Eintrag fehlt',error:'Einrichtung fehlgeschlagen'}[a.status]||a.status)}<br>${escape(a.error||'')}</p><p>Start im Benutzerkonto nach Windows-Anmeldung, ohne sichtbares Terminal. Keine Ausführung bei ausgeschaltetem PC. Das aktuelle Terminal kann bis zum bestätigten Hintergrundstart weiterlaufen. Der Hintergrundstarter übernimmt nach dessen Ende. Pfad muss erhalten bleiben.</p>${a.status!=='unsupported'?'<button id="startup-install">Autostart einrichten</button> <button id="startup-remove">Autostart entfernen</button>':''}</section>`}
$('#content').addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;try{if(b.id==='calendar-connect'){const r=await api('/api/calendar/connect',{method:'POST'});location.href=r.url}else if(b.id==='calendar-list'){const r=await api('/api/calendar/calendars');$('#calendar-options').innerHTML=r.items.map(i=>`<label><input type="checkbox" data-calendar value="${escape(i.id)}" ${(system.calendar.selected||[]).includes(i.id)?'checked':''}>${escape(i.summary||i.id)} · ${escape(i.timeZone)}</label>`).join('')+'<button id="calendar-select">Auswahl speichern</button>'}else if(b.id==='calendar-select'){await api('/api/calendar/select',{method:'POST',body:JSON.stringify({ids:[...document.querySelectorAll('[data-calendar]')].filter(n=>n.checked).map(n=>n.value)})});await refresh();toast('Kalender ausgewählt. Jetzt Termine abrufen.')}else if(b.id==='calendar-sync'){const r=await api('/api/calendar/sync',{method:'POST'});await refresh();toast(r.errors.length?r.errors.join('; '):r.updated_events+' Termine aktualisiert.')}else if(b.id==='calendar-disconnect'){if(confirm('Kalenderverbindung lokal entfernen? Importierte Termine bleiben erhalten.')){await api('/api/calendar/disconnect',{method:'POST'});await refresh()}}else if(b.id==='startup-install'){await api('/api/autostart/install',{method:'POST'});await refresh()}else if(b.id==='startup-remove'){if(confirm('Autostart bei Windows-Anmeldung entfernen? Die laufende App wird nicht beendet.')){await api('/api/autostart/remove',{method:'POST'});await refresh()}}}catch(error){toast(error.message)}});

let calendarCursor=today(),calendarMode='month',calendarArea='all';
function localDay(d){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function addDays(day,n){const d=new Date(day+'T12:00:00');d.setDate(d.getDate()+n);return localDay(d)}
function calendarRange(){const d=new Date(calendarCursor+'T12:00:00');if(calendarMode==='week'){const start=addDays(calendarCursor,-((d.getDay()+6)%7));return [start,addDays(start,6)]}const start=localDay(new Date(d.getFullYear(),d.getMonth(),1,12));return [start,localDay(new Date(d.getFullYear(),d.getMonth()+1,0,12))]}
function calendarEvent(r){const start=r.due;if(!start)return null;const raw=(r.body.match(/^Beginn: (.+)$/m)||[])[1]||'',endRaw=(r.body.match(/^Ende: (.+)$/m)||[])[1]||'';let end=start,label='Datum ohne Uhrzeit';if(raw.includes('T')){const d=new Date(raw);if(!Number.isNaN(d.getTime()))label=d.toLocaleTimeString('de-DE',{hour:'2-digit',minute:'2-digit'});const e=new Date(endRaw);if(endRaw.includes('T')&&!Number.isNaN(e.getTime()))end=localDay(e)}else if(/^\d{4}-\d{2}-\d{2}$/.test(raw)){label='Ganztägig';if(/^\d{4}-\d{2}-\d{2}$/.test(endRaw))end=addDays(endRaw,-1)}return {r,start,end:end<start?start:end,label,origin:r.source.startsWith('Google Kalender')?'Google':'Agent X'}}
function calendarItems(){return records.filter(r=>r.kind==='event'&&r.status!=='archived'&&(calendarArea==='all'||r.module===calendarArea)).map(calendarEvent).filter(Boolean).sort((a,b)=>a.start.localeCompare(b.start)||a.label.localeCompare(b.label)||a.r.title.localeCompare(b.r.title))}
function calendarMarkup(){const [first,last]=calendarRange(),items=calendarItems(),d=new Date(calendarCursor+'T12:00:00');const start=calendarMode==='week'?first:addDays(first,-((new Date(first+'T12:00:00').getDay()+6)%7));const count=calendarMode==='week'?7:42;const title=calendarMode==='week'?date(first)+' – '+date(last):d.toLocaleDateString('de-DE',{month:'long',year:'numeric'});const visible=items.filter(e=>e.start<=last&&e.end>=first);let cells='';for(let i=0;i<count;i++){const day=addDays(start,i),hits=items.filter(e=>e.start<=day&&e.end>=day);cells+=`<div class="calendar-day ${day===today()?'calendar-today':''} ${day<first||day>last?'calendar-outside':''}"><strong>${new Date(day+'T12:00:00').getDate()}${day===today()?' · Heute':''}</strong>${hits.slice(0,3).map(e=>`<button data-calendar-edit="${escape(e.r.id)}" title="${escape(e.r.title)} · ${escape(e.label)} · ${escape(e.origin)}">${escape(e.label)}<br>${escape(e.r.title)}<small>${escape(e.origin)} · ${escape(modules.find(m=>m[0]===e.r.module)?.[2]||e.r.module)}</small></button>`).join('')}${hits.length>3?`<small>+ ${hits.length-3} weitere · Liste unten</small>`:''}</div>`}return `<p>Termine aus allen Bereichen und ausgewählten Google-Kalendern. Google-Termine müssen zuvor abgerufen sein. Archivierte / abgesagte Termine sind ausgeblendet. Uhrzeiten entsprechen der Browserzeitzone.</p><div class="calendar-toolbar"><button data-calendar-nav="-1" aria-label="Vorheriger Zeitraum">←</button><strong>${escape(title)}</strong><button data-calendar-nav="1" aria-label="Nächster Zeitraum">→</button><button data-calendar-nav="today">Heute</button><button data-calendar-mode="month" aria-pressed="${calendarMode==='month'}">Monat</button><button data-calendar-mode="week" aria-pressed="${calendarMode==='week'}">Woche</button><label>Bereich<select id="calendar-area"><option value="all">Alle Bereiche</option>${modules.filter(m=>m[0]!=='commander'&&m[0]!=='crew').map(m=>`<option value="${m[0]}" ${calendarArea===m[0]?'selected':''}>${escape(m[2])}</option>`).join('')}</select></label></div><div class="calendar-scroll"><div class="calendar-grid">${['Mo','Di','Mi','Do','Fr','Sa','So'].map(x=>`<div class="calendar-weekday">${x}</div>`).join('')}${cells}</div></div><h3>${visible.length} Termine im Zeitraum</h3><div class="calendar-agenda">${visible.length?visible.map(e=>`<button data-calendar-edit="${escape(e.r.id)}"><strong>${escape(e.r.title)}</strong><br>${date(e.start)}${e.end!==e.start?' – '+date(e.end):''} · ${escape(e.label)}<br>${escape(e.origin)} · ${escape(modules.find(m=>m[0]===e.r.module)?.[2]||e.r.module)} · ${escape(statuses[e.r.status])}<br><small>Quelle: ${escape(e.r.source)} · Stand ${date(e.r.observed)}</small></button>`).join(''):'<p>Keine gespeicherten Termine in diesem Zeitraum. Prüfe Bereich, Zeitraum oder Google-Kalenderauswahl.</p>'}</div><p><a href="https://calendar.google.com/" target="_blank" rel="noopener noreferrer">Google Kalender öffnen ↗</a></p>`}
function renderCalendar(){if(csrf)$('#calendar-view').innerHTML=calendarMarkup()}
$('#open-calendar').addEventListener('click',()=>{renderCalendar();$('#calendar-dialog').showModal()});
$('#calendar-close').addEventListener('click',()=>$('#calendar-dialog').close());
$('#calendar-dialog').addEventListener('change',e=>{if(e.target.id==='calendar-area'){calendarArea=e.target.value;renderCalendar()}});
$('#calendar-dialog').addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.calendarEdit){const r=records.find(r=>r.id===b.dataset.calendarEdit);if(r){$('#calendar-dialog').close();edit(r)}}else if(b.dataset.calendarMode){calendarMode=b.dataset.calendarMode;renderCalendar()}else if(b.dataset.calendarNav){if(b.dataset.calendarNav==='today')calendarCursor=today();else if(calendarMode==='week')calendarCursor=addDays(calendarCursor,7*Number(b.dataset.calendarNav));else{const d=new Date(calendarCursor+'T12:00:00');calendarCursor=localDay(new Date(d.getFullYear(),d.getMonth()+Number(b.dataset.calendarNav),1,12))}renderCalendar()}});

function eventTiming(r){const result={};if(r.kind!=='event')return result;for(const [key,prefix] of [['start_time','Beginn'],['end_time','Ende']]){const raw=(String(r.body||'').match(new RegExp('^'+prefix+': (.+)$','m'))||[])[1];if(raw?.includes('T')){const d=new Date(raw);if(!Number.isNaN(d.getTime())){result[key]=String(d.getHours()).padStart(2,'0')+':'+String(d.getMinutes()).padStart(2,'0');if(key==='end_time')result.end_date=localDay(d)}}}return result}
function applyEventTime(data,id){const start=data.start_time||'',end=data.end_time||'',endDay=data.end_date||data.due;delete data.start_time;delete data.end_time;delete data.end_date;if(data.kind!=='event')return;if(!start&&!end){const old=records.find(r=>r.id===id);const prefix=old?.body.match(/^Beginn: (\d{4}-\d{2}-\d{2})\nEnde: [^\n]*\n?/);if(prefix)data.body=prefix[0]+data.body;return;}if(!data.due||!start)throw new Error('Für Uhrzeiten bitte Datum und Startuhrzeit angeben.');const begin=new Date(data.due+'T'+start+':00'),finish=end?new Date(endDay+'T'+end+':00'):null;if(Number.isNaN(begin.getTime())||(finish&&Number.isNaN(finish.getTime())))throw new Error('Ungültige Terminzeit.');if(finish&&finish<=begin)throw new Error('Das Ende muss nach dem Beginn liegen. Für Termine über Mitternacht das Enddatum ändern.');data.body='Beginn: '+begin.toISOString()+'\nEnde: '+(finish?finish.toISOString():'')+'\n'+data.body}
$('#record-form').addEventListener('change',e=>{if(e.target.name==='kind')$('#event-time-fields').hidden=e.target.value!=='event'});

$('#record-form').addEventListener('click',e=>{const b=e.target.closest('[data-priority-choice]');if(!b)return;$('#record-form').elements.namedItem('priority').value=b.dataset.priorityChoice;syncPriorityPicker()});
$('#record-form').addEventListener('change',e=>{if(e.target.name==='priority')syncPriorityPicker()});

$('#content').addEventListener('click',e=>{const b=e.target.closest('[data-workspace-filter]');if(!b)return;filter=b.dataset.workspaceFilter;if(view==='projects')render();else{pendingWorkspaceFilter=filter;location.hash='projects'}});
$('#assistant-dialog').addEventListener('click',e=>{if(e.target.closest('#assistant-crew-access')){$('#assistant-dialog').close();location.hash='crew'}});
